<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? '')); $courseId = valid_id($_GET['course_id'] ?? null); $status = (string) ($_GET['status'] ?? '');
$courseStatement = $pdo->prepare('SELECT id, title FROM courses ORDER BY title'); $courseStatement->execute(); $courses = $courseStatement->fetchAll();
$sql = 'SELECT enrollments.id, enrollments.name, enrollments.email, enrollments.phone, enrollments.status, enrollments.created_at, courses.title AS course_title FROM enrollments INNER JOIN courses ON courses.id = enrollments.course_id WHERE CONCAT_WS(" ", enrollments.name, enrollments.email, enrollments.phone) LIKE :search'; $params = ['search' => '%' . $search . '%'];
if ($courseId !== null) { $sql .= ' AND enrollments.course_id = :course_id'; $params['course_id'] = $courseId; }
if (in_array($status, ['Pending', 'Approved', 'Rejected', 'Contacted'], true)) { $sql .= ' AND LOWER(enrollments.status) = LOWER(:status)'; $params['status'] = $status; }
$sql .= ' ORDER BY enrollments.created_at DESC'; $statement = $pdo->prepare($sql); $statement->execute($params); $enrollments = $statement->fetchAll(); admin_header('Enrollments', 'enrollments/index.php');
?><div class="card table-card mb-3"><div class="card-body"><form class="row g-2" method="get"><div class="col-lg-5"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search name, email or phone..."></div><div class="col-lg-3"><select class="form-select" name="course_id"><option value="">All courses</option><?php foreach ($courses as $course): ?><option value="<?= e($course['id']) ?>" <?= $courseId === (int) $course['id'] ? 'selected' : '' ?>><?= e($course['title']) ?></option><?php endforeach; ?></select></div><div class="col-lg-2"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach (['Pending', 'Approved', 'Rejected', 'Contacted'] as $option): ?><option value="<?= e($option) ?>" <?= $status === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="col-lg-2"><button class="btn btn-outline-primary w-100" type="submit"><i class="bi bi-search me-1"></i>Filter</button></div></form></div></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Course</th><th>Phone</th><th>Status</th><th>Date</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($enrollments as $row): ?><tr><td><strong><?= e($row['name']) ?></strong><small class="d-block text-secondary"><?= e($row['email']) ?></small></td><td><?= e($row['course_title']) ?></td><td><?= e($row['phone']) ?></td><td><span class="badge text-bg-<?= strtolower($row['status']) === 'pending' ? 'warning' : (strtolower($row['status']) === 'rejected' ? 'danger' : 'success') ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="small text-secondary"><?= e(date('d M Y', strtotime($row['created_at']))) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="view.php?id=<?= e($row['id']) ?>">View</a> <a class="btn btn-sm btn-outline-secondary" href="edit.php?id=<?= e($row['id']) ?>">Status</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($row['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$enrollments): ?><tr><td colspan="6" class="text-center text-secondary py-5">No enrollments found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>